package com.nextrade.api.config; import com.nextrade.common.identifier.*; import com.nextrade.common.enumtype.*; import com.nextrade.service.ports.SessionRepository; import java.util.*; import java.util.concurrent.*; public final class InMemorySessionRepository implements SessionRepository {private final ConcurrentHashMap<SessionId,SessionRecord> store=new ConcurrentHashMap<>();public boolean create(SessionRecord r){return store.putIfAbsent(r.id(),r)==null;}public Optional<SessionRecord> findActive(SessionId id){return Optional.ofNullable(store.get(id)).filter(r->r.status()==SessionStatus.ACTIVE&&r.expiresAt().isAfter(java.time.Instant.now()));}public boolean rotate(SessionId oldId,SessionId newId,String digest){final boolean[] ok={false};store.computeIfPresent(oldId,(k,r)->{if(r.status()==SessionStatus.ACTIVE&&r.refreshDigest().equals(digest)&&r.expiresAt().isAfter(java.time.Instant.now())){ok[0]=true;return new SessionRecord(r.id(),r.userId(),r.refreshDigest(),SessionStatus.ROTATED,r.expiresAt());}return r;});return ok[0];}public int revoke(SessionId id){return store.computeIfPresent(id,(k,r)->new SessionRecord(r.id(),r.userId(),r.refreshDigest(),SessionStatus.REVOKED,r.expiresAt()))==null?0:1;}public int revokeAll(UserId id){AtomicInteger n=new AtomicInteger();store.replaceAll((k,r)->{if(r.userId().equals(id)&&r.status()==SessionStatus.ACTIVE){n.incrementAndGet();return new SessionRecord(r.id(),r.userId(),r.refreshDigest(),SessionStatus.REVOKED,r.expiresAt());}return r;});return n.get();}}
